 window.mdmAssetLookup=async term=>{const value=String(term||'').trim();if(!value)return null;const result=q('#cloud-scan-result');result.innerHTML='<div class="cloud-scan-banner neutral"><div><span class="result-kicker">Searching</span><span>Looking up '+escape(value)+'…</span></div></div>';try{const d=await api('/api/records/assets?q='+encodeURIComponent(value)+'&limit=20');const rows=d.rows||[];const normalized=value.toLowerCase();const asset=rows.find(a=>[a.asset_tag,a.barcode,a.serial_number,a.hostname,a.imei,a.mac_address].some(v=>String(v||'').toLowerCase()===normalized))||rows[0];if(asset){result.innerHTML='<div class="cloud-scan-banner success"><div><span class="result-kicker">✓ Asset Found</span><strong>'+escape(asset.asset_tag||asset.barcode||value)+'</strong><span>'+escape(asset.description||asset.model_name||asset.serial_number||'Registered asset')+'</span></div><button type="button" data-open-asset="'+escape(asset.asset_id)+'">Quick View</button></div>';return asset;}result.innerHTML='<div class="cloud-scan-banner warning"><div><span class="result-kicker">⚠ Asset Not Registered</span><strong>'+escape(value)+'</strong><span>No matching asset tag, barcode, or serial number was found.</span></div></div>';return null;}catch(e){result.innerHTML='<div class="cloud-scan-banner danger"><div><span class="result-kicker">Lookup Failed</span><span>'+escape(e.message)+'</span></div></div>';return null;}};
