 q('#import-local').onclick=async()=>{const records=typeof inventory!=='undefined'?inventory:[];if(!records.length){alert('No device inventory to import.');return;}await dialog('Import '+records.length+' device items',[f('category_id',['asset_categories','category_id']),f('asset_type_id',['asset_types','asset_type_id']),f('asset_class_id',['asset_classes','asset_class_id']),f('condition_id',['asset_conditions','condition_id']),f('current_location_id',['locations','location_id'],false)],{},async d=>{let count=0;for(const r of records){try{await api('/api/records/assets','POST',{...d,asset_tag:r.assetTag||r.barcode,barcode:r.barcode,serial_number:r.serialNumber||null,description:r.itemName||r.description||null,quantity:String(r.quantity||1),is_serialized:Number(r.quantity||1)===1?1:0});count++;}catch(e){throw Error(`${count} imported. Item ${r.barcode}: ${e.message}. Device records remain available.`);}}cache={};await loadRecords();await dashboard();});};
 (async()=>{try{const result=await api('/api/metadata');meta=result.tables;user=result.user;q('#account-role').textContent=user.roles.join(', ').replaceAll('_',' ');if(q('#account-name'))q('#account-name').textContent=user.name||user.display_name||user.username||q('#account-email')?.textContent?.split('@')[0]||'Account';q('#module-select').innerHTML=Object.entries(meta).sort(([a],[b])=>a==='assets'?-1:b==='assets'?1:a.localeCompare(b)).map(([t,m])=>`<option value="${t}">${title(m.module)} · ${title(t)}</option>`).join('');q('#module-select').value='assets';q('#cloud-export').hidden=!(user.super||user.permissions.includes('exports.view'));q('#import-local').hidden=!user.super;q('#users-nav').hidden=!user.super;document.querySelectorAll('[data-page="scanner"]').forEach(el=>el.hidden=!(user.super||user.permissions.includes('barcode.manage')));const restored=await ensureClientMasterDefaults();if(restored.length){cache={};console.info('Restored default master data:',restored.length);}if(!q('#records').hidden)await loadRecords();await dashboard();if(meta.inventory_sessions){const sessions=await data('inventory_sessions');q('#scan-session').innerHTML+=sessions.filter(s=>s.status==='ACTIVE').map(s=>{const expected=s.expected_count??s.expected_assets??s.total_expected??s.asset_count??'';return `<option value="${s.inventory_session_id}" data-expected="${escape(expected)}">${escape(s.session_name)}</option>`}).join('');}if(meta.locations){q('#scan-location').innerHTML+=(await data('locations')).map(l=>`<option value="${l.location_id}">${escape(l.location_name)}</option>`).join('');} }catch(e){q('#cloud-stats').textContent=e.message;}})();
